layers.vertex:
attribute vec3 aO; attribute float aT, aK; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){
      float u = uTime - aT, life = aK < .5 ? .4 : .75; if (u < 0. || u > life){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vP = position.xy*1.1; vU = u; vK = aK;
      if (aK < .5){ vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.25, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.35; mv.xy += position.xy*.42; gl_Position = projectionMatrix*mv; }   /* Fear: on the chest */
      else { float S = .62; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .04, -position.y*S), 1.); }        /* Root: only the immediate base of the feet */
    }

layers.fragment:
uniform vec3 uCW, uCT; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float h1(float n){ return fract(sin(n*91.7)*43758.5); }
    void main(){
      vec2 p = vP; float r = length(p), a = atan(p.x, p.y), lum = 0., hot = 0.;
      vec3 col = vK < .5 ? uCW : uCT;
      if (vK < .5){
        for (int j=0;j<2;j++){
          float t = clamp((vU - float(j)*.05)/.3, 0., 1.);
          float R = mix(1.0, .1, t*t*t);                                    // reverse ease-in: creeps in, then snaps shut
          float w = mix(.012, .03, t*t), f = smoothstep(0., .1, t)*(1. - smoothstep(.9, 1., t));
          lum += exp(-pow(abs(r - R)/w, 2.4))*f*(j == 0 ? 1. : .55); hot += lcore(r - R, w*.3)*f*.5;
        }
        lum += exp(-r*r*40.)*(vU > .3 && vU < .333 ? 1.6 : 0.);                 // 2-frame spark when it closes
      } else {
        float grow = 1. - pow(1. - clamp(vU/.14, 0., 1.), 3.), f = 1. - smoothstep(.45, .75, vU);
        for (int i=0;i<7;i++){
          float fi = float(i), th = fi*.8976 + (h1(fi) - .5)*.5;
          float along = dot(p, vec2(sin(th), cos(th))), off = abs(p.x*cos(th) - p.y*sin(th) + .05*sin(along*9. + fi*2.));   // wiggling tendril
          float L = (.55 + .4*h1(fi + 3.))*grow, s = clamp(along/max(L, .01), 0., 1.);
          float w = mix(.03, .004, s);                                      // thick at the feet, hair-fine at the tip
          lum += exp(-pow(off/w, 2.))*step(0., along)*smoothstep(L, L*.85, along)*smoothstep(.1, .18, along);
          float bs = L*.55, bt = th + (h1(fi + 5.) > .5 ? .6 : -.6);          // one short fork per tendril
          vec2 q = p - vec2(sin(th), cos(th))*bs, bd = vec2(sin(bt), cos(bt));
          float ba = dot(q, bd), bo = abs(q.x*bd.y - q.y*bd.x), bl = L*.35;
          lum += exp(-pow(bo/mix(.014, .003, clamp(ba/max(bl, .01), 0., 1.)), 2.))*step(0., ba)*smoothstep(bl, bl*.7, ba)*.8;
        }
        lum += exp(-pow(abs(r - .2)/.018, 2.4));                           // grip ring around the feet
        lum *= f; hot = lum*.25*(vU < .033 ? 3. : 1.);
      }
      vec3 o = col*lum + mix(col, vec3(1., .96, .95), .6)*hot;
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 1.);
    }
